//! Replicates `std::stof` (strtof) semantics for command-line parsing.

/// Parses a string like C++ `std::stof`.
/// Returns Err(()) when no conversion could be performed (C++ would throw
/// std::invalid_argument and the uncaught exception would abort the program).
///
/// Err(()) is also returned when the value is out of `float` range (C++ would
/// throw std::out_of_range); both exceptions are uncaught in the reference
/// program, so both observably abort with a nonzero exit and the same
/// "terminate called ..." stderr pattern (only the exception name differs).
///
/// Semantics replicated (glibc strtof, verified case-by-case against the
/// reference binary):
/// - leading ASCII whitespace (space, \t, \n, \v, \f, \r) is skipped;
/// - optional '+'/'-' sign;
/// - case-insensitive "inf"/"infinity" and "nan" (optionally "nan(chars)");
/// - decimal literals: digits with optional '.', at least one digit total
///   (".5" and "5." both valid), optional 'e'/'E' exponent that requires at
///   least one exponent digit — a bare "e"/"e+" is NOT part of the number,
///   so "1e" and "1e+" both parse as 1.0;
/// - hexadecimal literals "0x...": hex digits with optional '.', optional
///   binary 'p'/'P' exponent; "0x" with no hex digits parses as plain "0"
///   (strtof's subject sequence is just "0", the 'x' is left over);
/// - everything after the longest valid prefix is ignored
///   ("1.5xyz" -> 1.5, "1,5" -> 1.0);
/// - overflow: a value that rounds above f32::MAX -> Err (std::out_of_range);
/// - underflow: a non-zero value whose rounded result is subnormal or zero
///   -> Err (std::out_of_range), UNLESS the subnormal result is exact
///   (glibc only sets ERANGE for inexact subnormals; "0x1p-149" is accepted,
///   "1e-38" is not).
pub fn stof(s: &str) -> Result<f32, ()> {
    let b = s.as_bytes();
    let mut i = 0;
    while i < b.len() && matches!(b[i], b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r') {
        i += 1;
    }
    let sign_start = i;
    let neg = if i < b.len() && (b[i] == b'+' || b[i] == b'-') {
        let m = b[i] == b'-';
        i += 1;
        m
    } else {
        false
    };
    let rest = &b[i..];
    if rest.len() >= 3 && rest[..3].eq_ignore_ascii_case(b"inf") {
        return Ok(if neg { f32::NEG_INFINITY } else { f32::INFINITY });
    }
    if rest.len() >= 3 && rest[..3].eq_ignore_ascii_case(b"nan") {
        // An optional "(chars)" tail is simply not part of the value.
        return Ok(if neg { -f32::NAN } else { f32::NAN });
    }
    if rest.len() >= 2 && rest[0] == b'0' && (rest[1] | 0x20) == b'x' {
        if let Some(r) = parse_hex(&b[i + 2..], neg) {
            return r;
        }
        // "0x" with no hex digits: the subject sequence is just "0".
        return Ok(if neg { -0.0 } else { 0.0 });
    }
    parse_decimal(s, sign_start, i)
}

fn hex_val(c: u8) -> Option<u32> {
    match c {
        b'0'..=b'9' => Some((c - b'0') as u32),
        b'a'..=b'f' => Some((c - b'a' + 10) as u32),
        b'A'..=b'F' => Some((c - b'A' + 10) as u32),
        _ => None,
    }
}

/// Parses a hexadecimal float body (after "0x"). Returns None when there are
/// no hex digits at all, so the caller can fall back to the plain "0" prefix.
fn parse_hex(b: &[u8], neg: bool) -> Option<Result<f32, ()>> {
    let mut mantissa: f64 = 0.0;
    let mut nonzero = false;
    let mut frac_digits: i64 = 0;
    let mut j = 0;
    while let Some(d) = b.get(j).and_then(|&c| hex_val(c)) {
        mantissa = mantissa * 16.0 + d as f64;
        nonzero |= d != 0;
        j += 1;
    }
    let int_digits = j;
    if b.get(j) == Some(&b'.') {
        let mut k = j + 1;
        while let Some(d) = b.get(k).and_then(|&c| hex_val(c)) {
            mantissa = mantissa * 16.0 + d as f64;
            frac_digits += 1;
            nonzero |= d != 0;
            k += 1;
        }
        if k > j + 1 || int_digits > 0 {
            j = k;
        }
    }
    if int_digits == 0 && frac_digits == 0 {
        return None;
    }
    // Optional binary exponent 'p'/'P': only consumed with >= 1 digit.
    let mut exp: i64 = 0;
    if b.get(j).map_or(false, |&c| c | 0x20 == b'p') {
        let mut k = j + 1;
        let mut eneg = false;
        if k < b.len() && (b[k] == b'+' || b[k] == b'-') {
            eneg = b[k] == b'-';
            k += 1;
        }
        let dstart = k;
        let mut e: i64 = 0;
        while k < b.len() && b[k].is_ascii_digit() {
            e = (e * 10 + (b[k] - b'0') as i64).min(1_000_000);
            k += 1;
        }
        if k > dstart {
            exp = if eneg { -e } else { e };
        }
    }
    // f64 intermediate: exact for up to ~13 significant hex digits (53 bits);
    // longer hex mantissas may double-round, which no realistic CLI arg hits.
    let bin_exp = exp.saturating_sub(4 * frac_digits).clamp(-1_000_000, 1_000_000) as i32;
    let v = mantissa * 2f64.powi(bin_exp);
    Some(range_check(if neg { -v } else { v }, nonzero))
}

fn parse_decimal(s: &str, sign_start: usize, mut i: usize) -> Result<f32, ()> {
    let b = s.as_bytes();
    let mut nonzero = false;
    let mut digits = 0usize;
    while i < b.len() && b[i].is_ascii_digit() {
        nonzero |= b[i] != b'0';
        digits += 1;
        i += 1;
    }
    if i < b.len() && b[i] == b'.' {
        let mut k = i + 1;
        while k < b.len() && b[k].is_ascii_digit() {
            nonzero |= b[k] != b'0';
            digits += 1;
            k += 1;
        }
        if digits > 0 {
            i = k;
        }
    }
    if digits == 0 {
        return Err(()); // std::invalid_argument
    }
    let mut end = i;
    // Exponent: 'e'/'E', optional sign, at least one digit — else unconsumed.
    if b[i] | 0x20 == b'e' {
        let mut k = i + 1;
        if k < b.len() && (b[k] == b'+' || b[k] == b'-') {
            k += 1;
        }
        let dstart = k;
        while k < b.len() && b[k].is_ascii_digit() {
            k += 1;
        }
        if k > dstart {
            end = k;
        }
    }
    let text = &s[sign_start..end];
    // Rust's f32::from_str is correctly rounded (decimal -> f32), exactly
    // like strtof; it yields +/-inf on overflow and 0/subnormal on underflow.
    let f: f32 = text.parse().map_err(|_| ())?;
    if f.is_infinite() {
        return Err(()); // std::out_of_range
    }
    if nonzero && f.abs() < f32::MIN_POSITIVE {
        // Underflow: glibc sets ERANGE (std::out_of_range) unless the
        // subnormal/zero result is exact. The f64 parse of the same text is
        // exact whenever the true value equals an f32-representable number
        // (every f32 is an f32-exact f64), so comparing detects exactness.
        let v: f64 = text.parse().map_err(|_| ())?;
        if v == 0.0 || v != f as f64 {
            return Err(()); // std::out_of_range
        }
    }
    Ok(f)
}

/// Shared range check for the hex path: `v` is the f64 approximation of the
/// value, `nonzero` reports whether the mantissa had any non-zero digit.
fn range_check(v: f64, nonzero: bool) -> Result<f32, ()> {
    let f = v as f32;
    if f.is_infinite() {
        return Err(()); // std::out_of_range
    }
    if nonzero && f.abs() < f32::MIN_POSITIVE && (v == 0.0 || v != f as f64) {
        return Err(()); // std::out_of_range (inexact subnormal/zero)
    }
    Ok(f)
}

#[cfg(test)]
mod tests {
    use super::stof;

    #[test]
    fn basics() {
        assert_eq!(stof("0.3"), Ok(0.3f32));
        assert_eq!(stof("  2.5"), Ok(2.5));
        assert_eq!(stof("1.5xyz"), Ok(1.5));
        assert_eq!(stof(".5"), Ok(0.5));
        assert_eq!(stof("5."), Ok(5.0));
        assert_eq!(stof("+3"), Ok(3.0));
        assert_eq!(stof("1e"), Ok(1.0));
        assert_eq!(stof("1e+"), Ok(1.0));
        assert_eq!(stof("1e5"), Ok(100000.0));
        assert_eq!(stof("1E-2"), Ok(0.01));
        assert_eq!(stof("1,5"), Ok(1.0));
        assert_eq!(stof("007"), Ok(7.0));
        assert_eq!(stof("0x10"), Ok(16.0));
        assert_eq!(stof("0x1.8p1"), Ok(3.0));
        assert_eq!(stof("0x"), Ok(0.0));
        assert_eq!(stof("0x1p-149"), Ok(f32::from_bits(1)));
    }

    #[test]
    fn specials() {
        assert_eq!(stof("inf"), Ok(f32::INFINITY));
        assert_eq!(stof("-INF"), Ok(f32::NEG_INFINITY));
        assert_eq!(stof("infinity"), Ok(f32::INFINITY));
        assert!(stof("nan").unwrap().is_nan());
        assert!(stof("nan(1)").unwrap().is_nan());
        assert!(stof("-nan").unwrap().is_sign_negative());
        assert_eq!(stof("-0"), Ok(-0.0));
    }

    #[test]
    fn errors() {
        for s in ["abc", "", "   ", "+", ".", ".e2", "e5"] {
            assert_eq!(stof(s), Err(()), "{s:?}");
        }
        // out_of_range: overflow and inexact underflow
        for s in ["1e400", "-1e400", "1e-400", "1e-38", "1e-45", "3.5e38", "0x1p128"] {
            assert_eq!(stof(s), Err(()), "{s:?}");
        }
        // exact zero / exact subnormal do NOT throw
        assert_eq!(stof("0e999"), Ok(0.0));
        assert_eq!(stof("0x0p-999"), Ok(0.0));
        assert_eq!(stof("1.17549435e-38"), Ok(f32::MIN_POSITIVE));
    }
}

