/// Handles an optional "(tag)" after "nan". glibc interprets the tag with
/// strtoull(..., base 0) and folds it into the mantissa: quiet bit forced,
/// payload truncated to the low 23 bits; tag 0 (or no valid tag) yields the
/// default quiet NaN. A tag that overflows u64 sets ERANGE, which std::stof
/// turns into std::out_of_range.
fn nan_value(rest: &[u8], neg: bool) -> Result<f32, ()> {
    let mut payload: u64 = 0;
    if rest.first() == Some(&b'(') {
        let mut j = 1;
        while j < rest.len() && (rest[j].is_ascii_alphanumeric() || rest[j] == b'_') {
            j += 1;
        }
        if j < rest.len() && rest[j] == b')' {
            payload = parse_nan_tag(&rest[1..j])?;
        }
    }
    let mantissa = ((payload as u32) | 0x40_0000) & 0x7f_ffff;
    let mut bits = 0x7f80_0000u32 | mantissa;
    if neg {
        bits |= 0x8000_0000;
    }
    Ok(f32::from_bits(bits))
}
